@import 'tailwindcss';

:root{--sky-top:#bcd8f2;--sky-low:#eef2e2;--ink:#1d2a14;--soft-ink:#4b5a3e;--sun:#ffd23f;--leaf:#79a564;--card:rgba(255,255,255,.62);--line:rgba(29,42,20,.12)}
*{box-sizing:border-box}
html,body{margin:0;min-height:100%}
body{background:linear-gradient(180deg,var(--sky-top) 0%,#d9e8f1 45%,var(--sky-low) 100%);color:var(--ink);font-family:var(--font-sans),'Segoe UI',sans-serif;font-size:15px;overflow-x:hidden}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
button:disabled{cursor:not-allowed;opacity:.45}
button:focus-visible,input:focus-visible{outline:3px solid #1d2a14;outline-offset:3px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Intro: twks-style single line that splits to the edges */
.intro{position:fixed;inset:0;z-index:50;background:#000;cursor:pointer;transition:background-color .9s ease .35s,opacity .5s ease .9s}
.intro-word{position:absolute;top:50%;color:#fff;font-weight:500;font-size:clamp(17px,1.5vw,22px);letter-spacing:.01em;white-space:nowrap;translate:0 -50%;transition:left 1s cubic-bezier(.76,0,.24,1),transform 1s cubic-bezier(.76,0,.24,1),color .6s ease .4s}
.intro-left{left:50%;transform:translateX(calc(-100% - 14px))}
.intro-right{left:calc(50% + 14px);transform:translateX(0)}
.intro-hold .intro-word{animation:intro-in .7s cubic-bezier(.2,.7,.2,1) both}
.intro-split{background:transparent;opacity:0;pointer-events:none}
.intro-split .intro-left{left:24px;transform:translateX(0)}
.intro-split .intro-right{left:calc(100% - 24px);transform:translateX(-100%)}
.intro-split .intro-word{color:var(--ink)}
@keyframes intro-in{from{opacity:0;translate:0 calc(-50% + 14px)}to{opacity:1;translate:0 -50%}}

/* Scenery */
.scenery{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.hills{position:absolute;left:0;right:0;bottom:0;width:100%;height:38vh}
.cloud{position:absolute;width:200px;height:60px;border-radius:60px;background:#fff;opacity:.85;filter:blur(1px);box-shadow:40px -26px 0 8px #fff,95px -10px 0 -2px #fff,-30px -6px 0 -6px #fff;animation:drift 60s linear infinite}
.cloud-a{top:12%;left:-10%}
.cloud-b{top:24%;left:40%;scale:.7;animation-duration:85s;animation-delay:-30s}
.cloud-c{top:7%;left:75%;scale:.9;animation-duration:70s;animation-delay:-50s}
@keyframes drift{from{translate:0 0}to{translate:120vw 0}}

/* Layout */
.corner{position:fixed;top:0;left:0;right:0;z-index:5;display:flex;justify-content:space-between;padding:20px 24px;font-weight:500;font-size:clamp(15px,1.3vw,19px)}
.corner-mark b{font-weight:700}
.corner-status{color:var(--soft-ink)}
.garden{position:relative;min-height:100vh}
.stage{position:relative;z-index:1;display:grid;grid-template-columns:minmax(260px,1fr) minmax(320px,1.1fr);grid-template-areas:"flower copy" "flower dock";align-items:center;column-gap:4vw;max-width:1320px;min-height:100vh;margin:0 auto;padding:84px 5vw 40px}
.flower{grid-area:flower;display:flex;justify-content:center;align-self:end}
.flower svg{height:min(80vh,720px);width:auto;max-width:100%;overflow:visible;transform-origin:50% 100%;animation:sway 7s ease-in-out infinite}
.copy{grid-area:copy;align-self:end;display:flex;flex-direction:column;gap:18px}
.dock{grid-area:dock;align-self:start;display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin-top:28px}

/* Words */
.headline{margin:0;font-family:var(--font-display),var(--font-sans),sans-serif;font-weight:800;font-size:clamp(30px,4.1vw,62px);line-height:1.02;letter-spacing:-.025em;text-wrap:balance}
.headline-long{font-size:clamp(26px,3.1vw,46px);line-height:1.04}
.dialogue{display:flex;flex-direction:column;gap:8px;max-width:620px}
