.said-thinking{margin:0;color:var(--soft-ink);animation:pulse 1.2s ease-in-out infinite}
.notice{margin:0;padding:10px 14px;border-radius:14px;background:var(--card);border:1px solid var(--line);font-size:14px;width:fit-content;max-width:100%}
.error{margin:0;padding:10px 14px;border-radius:14px;background:#fff1ec;border:1px solid #f3b8a6;color:#8a2c13;font-size:14px;max-width:620px}

/* Controls */
.pill{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:999px;background:var(--card);border:1px solid var(--line);backdrop-filter:blur(8px);font-weight:500;font-size:14px;transition:background .2s,transform .2s}
.pill:hover:not(:disabled){background:#fff;transform:translateY(-1px)}
.pill-on{background:var(--ink);color:#fff;border-color:var(--ink)}
