.start{display:inline-flex;align-items:center;gap:10px;padding:16px 26px;border-radius:999px;background:var(--ink);color:#fff;font-weight:600;font-size:17px;box-shadow:0 10px 30px rgba(29,42,20,.25);transition:transform .2s}
.start:hover:not(:disabled){transform:translateY(-2px)}
