@import 'tailwindcss';

:root{--sky-top:#bcd8f2;--sky-low:#eef2e2;--ink:#1d2a14;--soft-ink:#4b5a3e;--sun:#ffd23f;--leaf:#79a564;--card:rgba(255,255,255,.62);--line:rgba(29,42,20,.12)}
*{box-sizing:border-box}
html,body{margin:0;min-height:100%}
body{background:linear-gradient(180deg,var(--sky-top) 0%,#d9e8f1 45%,var(--sky-low) 100%);color:var(--ink);font-family:var(--font-sans),'Segoe UI',sans-serif;font-size:15px;overflow-x:hidden}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
button:disabled{cursor:not-allowed;opacity:.45}
button:focus-visible,input:focus-visible{outline:3px solid #1d2a14;outline-offset:3px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Intro: twks-style single line that splits to the edges */
.intro{position:fixed;inset:0;z-index:50;background:#000;cursor:pointer;transition:background-color .9s ease .35s,opacity .5s ease .9s}
.intro-word{position:absolute;top:50%;color:#fff;font-weight:500;font-size:clamp(17px,1.5vw,22px);letter-spacing:.01em;white-space:nowrap;translate:0 -50%;transition:left 1s cubic-bezier(.76,0,.24,1),transform 1s cubic-bezier(.76,0,.24,1),color .6s ease .4s}
.intro-left{left:50%;transform:translateX(calc(-100% - 14px))}
.intro-right{left:calc(50% + 14px);transform:translateX(0)}
.intro-hold .intro-word{animation:intro-in .7s cubic-bezier(.2,.7,.2,1) both}
.intro-split{background:transparent;opacity:0;pointer-events:none}
.intro-split .intro-left{left:24px;transform:translateX(0)}
.intro-split .intro-right{left:calc(100% - 24px);transform:translateX(-100%)}
.intro-split .intro-word{color:var(--ink)}
@keyframes intro-in{from{opacity:0;translate:0 calc(-50% + 14px)}to{opacity:1;translate:0 -50%}}

/* Scenery */
.scenery{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.hills{position:absolute;left:0;right:0;bottom:0;width:100%;height:38vh}
.cloud{position:absolute;width:200px;height:60px;border-radius:60px;background:#fff;opacity:.85;filter:blur(1px);box-shadow:40px -26px 0 8px #fff,95px -10px 0 -2px #fff,-30px -6px 0 -6px #fff;animation:drift 60s linear infinite}
.cloud-a{top:12%;left:-10%}
.cloud-b{top:24%;left:40%;scale:.7;animation-duration:85s;animation-delay:-30s}
.cloud-c{top:7%;left:75%;scale:.9;animation-duration:70s;animation-delay:-50s}
@keyframes drift{from{translate:0 0}to{translate:120vw 0}}

/* Layout */
.corner{position:fixed;top:0;left:0;right:0;z-index:5;display:flex;justify-content:space-between;padding:20px 24px;font-weight:500;font-size:clamp(15px,1.3vw,19px)}
.corner-mark b{font-weight:700}
.corner-status{color:var(--soft-ink)}
.garden{position:relative;min-height:100vh}
.stage{position:relative;z-index:1;display:grid;grid-template-columns:minmax(260px,1fr) minmax(320px,1.1fr);grid-template-areas:"flower copy" "flower dock";align-items:center;column-gap:4vw;max-width:1320px;min-height:100vh;margin:0 auto;padding:84px 5vw 40px}
.flower{grid-area:flower;display:flex;justify-content:center;align-self:end}
.flower svg{height:min(80vh,720px);width:auto;max-width:100%;overflow:visible;transform-origin:50% 100%;animation:sway 7s ease-in-out infinite}
.copy{grid-area:copy;align-self:end;display:flex;flex-direction:column;gap:18px}
.dock{grid-area:dock;align-self:start;display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin-top:28px}

/* Words */
.headline{margin:0;font-family:var(--font-display),var(--font-sans),sans-serif;font-weight:800;font-size:clamp(30px,4.1vw,62px);line-height:1.02;letter-spacing:-.025em;text-wrap:balance}
.headline-long{font-size:clamp(26px,3.1vw,46px);line-height:1.04}
.dialogue{display:flex;flex-direction:column;gap:8px;max-width:620px}
.said-you{margin:0;font-size:14px;color:var(--soft-ink)}
.said-flower{margin:0;font-size:clamp(17px,1.4vw,21px);font-weight:500;line-height:1.35}
.said-thinking{margin:0;color:var(--soft-ink);animation:pulse 1.2s ease-in-out infinite}
.notice{margin:0;padding:10px 14px;border-radius:14px;background:var(--card);border:1px solid var(--line);font-size:14px;width:fit-content;max-width:100%}
.error{margin:0;padding:10px 14px;border-radius:14px;background:#fff1ec;border:1px solid #f3b8a6;color:#8a2c13;font-size:14px;max-width:620px}

/* Controls */
.pill{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:999px;background:var(--card);border:1px solid var(--line);backdrop-filter:blur(8px);font-weight:500;font-size:14px;transition:background .2s,transform .2s}
.pill:hover:not(:disabled){background:#fff;transform:translateY(-1px)}
.pill-on{background:var(--ink);color:#fff;border-color:var(--ink)}
.pill-on:hover:not(:disabled){background:var(--ink)}
.pill-solid{background:var(--ink);color:#fff}
.pill-icon{padding:10px 12px}
.start{display:inline-flex;align-items:center;gap:10px;padding:16px 26px;border-radius:999px;background:var(--ink);color:#fff;font-weight:600;font-size:17px;box-shadow:0 10px 30px rgba(29,42,20,.25);transition:transform .2s}
.start:hover:not(:disabled){transform:translateY(-2px)}
.mic{display:grid;place-items:center;width:76px;height:76px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff3a6,var(--sun) 55%,#f0a414);color:var(--ink);box-shadow:0 12px 28px rgba(240,164,20,.45),inset 0 -6px 12px rgba(0,0,0,.08);transition:transform .2s}
.mic:hover:not(:disabled){transform:scale(1.05)}
.mic-on{background:radial-gradient(circle at 35% 30%,#ffb2a0,#ff6b4a 60%,#d9431f);color:#fff;animation:ring 1.4s ease-out infinite}
.composer{display:flex;align-items:center;flex:1 1 260px;min-width:0;padding:6px 6px 6px 18px;border-radius:999px;background:var(--card);border:1px solid var(--line);backdrop-filter:blur(8px)}
.composer input{flex:1;min-width:0;border:0;background:transparent;padding:10px 0;outline:none}
.composer button{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:var(--ink);color:#fff}
.dock-actions{display:flex;gap:8px;width:100%}

/* Wardrobe (after Lacoste's Polo Factory: deep green, mint, oval badge) */
.wardrobe{--mint:#d5f0bd;width:100%;max-width:620px;padding:16px 18px 14px;border-radius:26px;background:#3e5c41;color:var(--mint);box-shadow:0 18px 40px rgba(40,62,40,.28)}
.wardrobe-head{display:flex;justify-content:space-between;align-items:center}
.wardrobe-badge{padding:6px 16px;border:1.5px solid currentColor;border-radius:50%;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase}
.wardrobe-count{font-size:12px;font-variant-numeric:tabular-nums;opacity:.8}
.rail{position:relative;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-top:18px}
.rail::before{content:'';position:absolute;top:0;left:-6px;right:-6px;height:5px;border-radius:5px;background:linear-gradient(#e8d39a,#b8955a);box-shadow:0 2px 4px rgba(0,0,0,.25)}
.hanger{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;padding:0 2px 6px;color:var(--mint);border-radius:14px;transform-origin:50% 0;transition:translate .25s ease}
.hanger:hover{translate:0 2px}
.hanger-hook{width:58%;height:auto;margin-top:-4px}
.hanger-icon{width:100%;height:58px;padding:5px;margin-top:-6px;border-radius:14px;background:rgba(213,240,189,.1);border:1.5px solid rgba(213,240,189,.18);transition:background .25s}
.hanger-label{font-size:11px;line-height:1.15;text-align:center}
.hanger-on{animation:swing .7s ease-out}
.hanger-on .hanger-icon{background:var(--mint);border-color:var(--mint)}
.hanger-on .hanger-label{font-weight:700;color:#fff}
.hanger:focus-visible{outline:2px solid #fff;outline-offset:2px}
.wardrobe-pick{display:flex;align-items:center;gap:12px;margin-top:10px;padding-top:12px;border-top:1px solid rgba(213,240,189,.22)}
.wardrobe-arrow{display:grid;place-items:center;flex:none;width:38px;height:38px;border-radius:50%;border:1.5px solid currentColor;color:var(--mint);transition:background .2s,color .2s}
.wardrobe-arrow:hover{background:var(--mint);color:#3e5c41}
.wardrobe-text{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:center}
.wardrobe-text strong{font-family:var(--font-display),sans-serif;font-size:21px;font-weight:800;color:#fff}
.wardrobe-text span{font-size:13px;opacity:.85}
.outfit{transform-box:fill-box;transform-origin:50% 0;animation:dress .6s cubic-bezier(.3,1.45,.5,1)}
@keyframes swing{0%{rotate:0deg}25%{rotate:7deg}55%{rotate:-4deg}80%{rotate:2deg}100%{rotate:0deg}}
@keyframes dress{from{translate:0 -36px;opacity:0;scale:1.06}to{translate:0 0;opacity:1;scale:1}}

/* Feedback */
.report{display:flex;flex-direction:column;gap:16px;max-width:660px;padding:22px;border-radius:24px;background:var(--card);border:1px solid var(--line);backdrop-filter:blur(10px)}
.report-summary{margin:0;font-size:17px;line-height:1.45}
.report-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.report-grid h2{margin:0 0 6px;font-family:var(--font-display),sans-serif;font-size:18px;font-weight:800}
.report-grid p{margin:0 0 6px;font-size:14px;line-height:1.45}
.report blockquote{margin:0;padding-left:14px;border-left:4px solid var(--sun);font-size:16px;font-weight:500}
.report .pill{width:fit-content}

/* Sunflower motion */
.flower-head,.petals,.eyes,.talking-mouth,.face{transform-box:fill-box;transform-origin:center}
.petals-front{animation:breathe 4.5s ease-in-out infinite}
.eyes{animation:blink 5.5s infinite}
.face{animation:pop .35s cubic-bezier(.3,1.6,.5,1)}
.face-line{fill:none;stroke:#2b1a10;stroke-width:6;stroke-linecap:round;stroke-linejoin:round}
.flower-listening .flower-head{scale:1.05;transition:scale .4s cubic-bezier(.3,1.6,.5,1)}
.flower-thinking .flower-head{animation:ponder 2.4s ease-in-out infinite}
.flower-speaking .flower-head{animation:bob .38s ease-in-out infinite alternate}
.talking-mouth{animation:talk .22s ease-in-out infinite alternate}
@keyframes sway{0%,100%{rotate:-1.6deg}50%{rotate:1.6deg}}
@keyframes breathe{0%,100%{scale:1}50%{scale:1.03}}
