@keyframes ring{0%{box-shadow:0 0 0 0 rgba(255,107,74,.5)}100%{box-shadow:0 0 0 22px rgba(255,107,74,0)}}
@keyframes pulse{0%,100%{opacity:.4}50%{opacity:1}}

